n=10; sweep() { for e in /proc/[0-9]*/environ; do p=${e#/proc/}; p=${p%/environ}; [ "$p" = "$$" ] && continue; tr '\0' '\n' 2>/dev/null < "$e" | grep -Eqx "DISPLAY=(unix|localhost)?:$n(\.[0-9]+)?|BREADSTICK_HEADLESS=1" || case "$(tr '\0' ' ' 2>/dev/null < /proc/$p/cmdline)" in *"BREADSTICK_HEADLESS=1 "*"export DISPLAY=\":$n\""*) ;; *) continue ;; esac; kill -"$1" "$p" 2>/dev/null; done; }; sweep TERM; x=$(tr -cd 0-9 < /tmp/.X$n-lock 2>/dev/null); if [ -n "$x" ]; then case "$(cat /proc/$x/comm 2>/dev/null)" in Xvnc|Xtigervnc) kill "$x" 2>/dev/null; i=0; while kill -0 "$x" 2>/dev/null && [ $i -lt 20 ]; do sleep 0.1; i=$((i+1)); done; kill -9 "$x" 2>/dev/null ;; esac; fi; sleep 1; sweep KILL; rm -f /tmp/.X$n-lock /tmp/.X11-unix/X$n /run/bsl/headless/passwd; true
